WFJ.Data.add("book", {
  ["583fefc4939fe6ab"] = { "⟦Hillsbrad Town Registry=Registro della Città di Colletorto⟧\n\nNoi, il popolo di ⟦Hillsbrad=Colletorto⟧, giuriamo solennemente la nostra fede e la nostra devozione all'⟦Alliance=Alleanza⟧ sostenuta dai grandi monarchi, re Magni Barbabronzea di ⟦Ironforge=Forgiardente⟧ e re Anduin Wrynn di ⟦Stormwind=Roccavento⟧.\n\nQui è custodito il registro cittadino, allo scopo di governare questa bella città ai piedi delle grandi ⟦Alterac Mountains=Montagne d'Alterac⟧ e di tenere nota di coloro che hanno pagato le tasse ai loro re e alla grande e onnipotente ⟦Alliance=Alleanza⟧.", "." },
  ["585527f6544cf056"] = { "Caro William,\n\nsono passati anni dall'ultima volta che ci siamo parlati, ma confido che tu e tuo fratello stiate bene e che la tua bottega di speziale prosperi.\n\nDevo chiederti un favore, William. In breve, mio nipote Tommy Joe ha perso il cuore per la giovane Maybell Maclure. E anche se si adorano... le nostre famiglie, be', le nostre famiglie sono in lite da anni.", "." },
  ["586130b76d9b1940"] = { "I sinistri agenti della Legione Infuocata, banditi quando il ⟦Well of Eternity=Pozzo dell'Eternità⟧ era crollato, furono attirati di nuovo nel mondo dagli incauti incantesimi dei maghi di Dalaran. Benché questi demoni relativamente deboli non si presentassero in forze, seminarono notevole confusione e caos per le strade di Dalaran.", "." },
  ["586bd320bb117205"] = { "Gli altri Titani cercarono di convincerlo del suo errore e di placare le sue emozioni furiose, ma egli liquidò le loro convinzioni più ottimistiche come illusioni di comodo. Abbandonate per sempre le loro schiere in preda all'ira, Sargeras partì per trovare il proprio posto nell'universo. Benché il Pantheon fosse addolorato per la sua partenza, i Titani non avrebbero mai potuto prevedere fin dove si sarebbe spinto il loro fratello perduto.", "." },
  ["58b179b700716b86"] = { "I perfidi e intriganti signori del terrore misero intere nazioni l'una contro l'altra, manipolandole fino a un odio e a una diffidenza ciechi. Sargeras sconfisse facilmente i Nathrezim, ma la loro corruzione lo segnò profondamente.", "." },
})
